package com.eventease.rag.assistant;

import java.util.Collections;
import java.util.List;

/**
 * Encapsulates the grounded answer generated by the assistant, along with citations and retrieval telemetry.
 */
public class GroundedAnswerResponse {

    private final String answer;
    private final boolean grounded;
    private final boolean evidenceFound;
    private final List<CitationSource> sources;
    private final double topSimilarityScore;
    private final String modelUsed;
    private final String fallbackReason;

    private GroundedAnswerResponse(
            String answer,
            boolean grounded,
            boolean evidenceFound,
            List<CitationSource> sources,
            double topSimilarityScore,
            String modelUsed,
            String fallbackReason
    ) {
        this.answer = answer;
        this.grounded = grounded;
        this.evidenceFound = evidenceFound;
        this.sources = sources != null ? Collections.unmodifiableList(sources) : Collections.emptyList();
        this.topSimilarityScore = topSimilarityScore;
        this.modelUsed = modelUsed;
        this.fallbackReason = fallbackReason;
    }

    public static GroundedAnswerResponse grounded(
            String answer,
            List<CitationSource> sources,
            double topSimilarityScore,
            String modelUsed
    ) {
        return new GroundedAnswerResponse(answer, true, true, sources, topSimilarityScore, modelUsed, null);
    }

    public static GroundedAnswerResponse insufficientEvidence(double topSimilarityScore) {
        String message = "I do not have sufficient information in the published event documentation to answer your question.";
        return new GroundedAnswerResponse(message, false, false, Collections.emptyList(), topSimilarityScore, null, "INSUFFICIENT_EVIDENCE");
    }

    public static GroundedAnswerResponse fallback(
            String fallbackMessage,
            List<CitationSource> sources,
            double topSimilarityScore,
            String fallbackReason
    ) {
        return new GroundedAnswerResponse(fallbackMessage, false, true, sources, topSimilarityScore, null, fallbackReason);
    }

    public static GroundedAnswerResponse invalidRequest(String message) {
        return new GroundedAnswerResponse(message, false, false, Collections.emptyList(), 0.0, null, "INVALID_REQUEST");
    }

    public String getAnswer() {
        return answer;
    }

    public boolean isGrounded() {
        return grounded;
    }

    public boolean isEvidenceFound() {
        return evidenceFound;
    }

    public List<CitationSource> getSources() {
        return sources;
    }

    public double getTopSimilarityScore() {
        return topSimilarityScore;
    }

    public String getModelUsed() {
        return modelUsed;
    }

    public String getFallbackReason() {
        return fallbackReason;
    }

    @Override
    public String toString() {
        return "GroundedAnswerResponse{" +
                "grounded=" + grounded +
                ", evidenceFound=" + evidenceFound +
                ", sourcesCount=" + sources.size() +
                ", topSimilarityScore=" + String.format("%.4f", topSimilarityScore) +
                ", fallbackReason='" + fallbackReason + '\'' +
                '}';
    }
}
